import json
def outline(p, depth=2):
    d=json.load(open(p,encoding='utf-8'))
    print("=====",p)
    def walk(o,pre,lvl):
        if lvl>depth: return
        if isinstance(o,dict):
            for k,v in o.items():
                if isinstance(v,(dict,list)):
                    print(f"{pre}{k}: {type(v).__name__}[{len(v)}]")
                    walk(v,pre+"  ",lvl+1)
                else:
                    print(f"{pre}{k}: {str(v)[:120]}")
        elif isinstance(o,list) and o:
            print(f"{pre}[0]:"); walk(o[0],pre+"  ",lvl+1)
    walk(d,"",0)
outline("work/asset-lineage/original-family.json",2)
outline("work/asset-lineage/plar-ready.json",2)
EOF

